\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/01_Figure_1_1_Architect.jpg}
\caption{From coding tools to whole-process software engineering. Conceptual redraw of W153, original Figure 1; \workref{W153}. Timeline simplified and not a historical adoption-rate estimate. The expanding scope runs from prescribed phases to iterative, socio-technical human--agent systems.}
\label{fig:ch01-research-1}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/02_Figure_1_2_Architect.jpg}
\caption{The software lifecycle extends beyond generated code. Conceptual redraw of W153, original Figure 2; \workref{W153}. The full lifecycle is a research vision, not a validated universal process.}
\label{fig:ch01-research-2}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/04_Figure_2_1_Architect.jpg}
\caption{Perceived speed and measured task time disagree. Reported figures of W023, original Figure 1; \workref{W023}. Time-change estimand: forecasts $-24\%$, post hoc estimates $-20\%$, regression-adjusted measured effect $+19\%$; not a prediction for 2026 models.}
\label{fig:ch02-research-1}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/05_Figure_2_2_Architect.jpg}
\caption{Time moves from writing toward agent supervision. Qualitative redraw of W023, original Figure 6; \workref{W023}. Reorganization of reported task categories without reconstructing unavailable bar heights. Rectangles identify categories, not time percentages.}
\label{fig:ch02-research-2}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/06_Figure_3_1_Architect.jpg}
\caption{SE for humans and SE for agents. Conceptual redraw of W152, original Figure 1; \workref{W152}. Conceptual summary of the SASE vision, not an implemented organizational trial. The two modes exchange explicit artifacts rather than unbounded instructions.}
\label{fig:ch03-research-1}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/07_Figure_3_2_Architect.jpg}
\caption{Agency and orchestration are separate configuration choices. Original engineering teaching diagram informed by Osmani's two-axis discussion, \workref{O010}. The quadrants are examples, not measured risk categories; policy authority and independent checking are needed in every configuration. Every quadrant also requires bounded scope and a named acceptance owner.}
\label{fig:osmani-agency-orchestration}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/08_Figure_3_3_Architect.jpg}
\caption{Task type influences observed agent PR merge rates. Reported task-category summaries of W191, original Figure 1; \workref{W191}. Rates are from the original task-category aggregation and are confounded by repository and task mix. They are not conditional success probabilities for a new project.}
\label{fig:ch03-research-2}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/09_Figure_3_4_Architect.jpg}
\caption{The controls stay; the execution mechanism can change. Original conceptual synthesis prompted by \workref{P110}'s question and the preceding \workref{O012} discussion. Alternatives are unranked: no performance result or claim of product sufficiency is implied.}
\label{fig:controls_execution_P110}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/10_Figure_4_1_Architect.jpg}
\caption{Deterministic control surrounds model-generated substeps. Conceptual redraw of W151, original Figure 2; \workref{W151}. Based on the Source Code Agent design; its original evaluation was travel planning, not brownfield change approval. Change approval and independent acceptance remain external to model output.}
\label{fig:ch04-research-1}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/11_Figure_4_2_Architect.jpg}
\caption{A controlled tool interaction can be re-entered after a late change. Conceptual redraw of W151, original Figure 4; \workref{W151}. Adapts the controlled interaction flow to the chapter’s illustrative intent-delta workflow. Late intent is an explicit control-plane event, not a silent rewrite.}
\label{fig:ch04-research-2}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/13_Figure_5_1_Architect.jpg}
\caption{How post-merge quality is measured. Conceptual redraw of W054, original Figure 1; \workref{W054}. Schematic of the paper’s four-stage methods and data lineage, not a quality ranking. Smells and rework are observational measures, not deployed incidents.}
\label{fig:ch05-research-1}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/14_Figure_5_2_Architect.jpg}
\caption{Prior AI exposure changes the velocity signal, not the need for quality gates. Qualitative redraw of W001, original Figure 2; \workref{W001}. The source’s staggered-adoption estimates are grouped here only by direction and cohort. The boxes encode neither effect sizes nor incident rates.}
\label{fig:ch05-research-2}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/15_Figure_6_1_Architect.jpg}
\caption{The package-hallucination supply-chain path. Conceptual redraw of W043, original Figure 1; \workref{W043}. Threat pathway from the paper; deliberately omits exploit payloads and attack instructions.}
\label{fig:ch06-research-1}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/16_Figure_6_2_Architect.jpg}
\caption{Untrusted repository instructions must not become tool authority. Conceptual redraw of W060, original Figure 1; \workref{W060}. Conceptual security-boundary adaptation; this is a recommended control, not the original experiment’s measured defense effectiveness. The runtime must enforce action authority independently of interpreted content.}
\label{fig:ch06-research-2}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/17_Figure_7_1_Architect.jpg}
\caption{Independent labels matter when checkers share errors. Reported figures of W079, original Figure 1 (Helm panel); \workref{W079}. Average conditional agreement $0.60$ versus uniform-choice baseline $1/3$ for the Helm setup; bars replace the original model-pair heatmap. This is not a universal coding-agent error rate; another model is not an independent oracle by default.}
\label{fig:ch07-research-1}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/18_Figure_7_2_Architect.jpg}
\caption{Reliability grows through an evidence-gate ladder. Conceptual redraw of W095, original Figure 2; \workref{W095}. Original author presents a synthesis framework, not an empirically validated universal standard. A benchmark pass supplies evidence for one gate, not production acceptance.}
\label{fig:ch07-research-2}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/20_Figure_8_1_Architect.jpg}
\caption{A reviewer can fix code or regress it. Reported figures of W102, original Figure 1; \workref{W102}. Published paired task counts; conditions restricted to complete-case LiveCodeBench problems, not repository change reviews.}
\label{fig:ch08-research-1}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/21_Figure_8_2_Architect.jpg}
\caption{More review spending can improve or worsen correctness. Reported figures of W102, original Figure 2; \workref{W102}. Published task-level means transformed to compact approximate coordinates; excludes confidence intervals and deployment costs.}
\label{fig:ch08-research-2}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/22_Figure_9_1_Architect.jpg}
\caption{Episodic and semantic memory answer different questions. Conceptual redraw of W160, original Figure 2; \workref{W160}. A software-engineering adaptation of AriGraph’s world-model architecture; AriGraph itself was evaluated on text games. Software memory additionally needs contract version and invalidation status.}
\label{fig:ch09-research-1}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/23_Figure_9_2_Architect.jpg}
\caption{Memory must survive compaction and reset by harness policy. Conceptual redraw of W157, original Figure 1; \workref{W157}. Compresses the paper’s typed pages, compaction boundary and validated journal; no performance claims. State integrity is a harness obligation, not a prompt request.}
\label{fig:ch09-research-2}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/24_Figure_10_1_Architect.jpg}
\caption{Reusable expert-curated code tours support onboarding. Conceptual redraw of W156, original Figure 1; \workref{W156}. Source compares expert/learner views of one-to-one mentoring and the LACY tool; this simplifies the workflow. Expert curation is the distinguishing step; exploratory AI tours are less authoritative.}
\label{fig:ch10-research-1}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/25_Figure_10_2_Architect.jpg}
\caption{Task completion and immediate comprehension are separate outcomes. Qualitative redraw of W118, original Figure 1; \workref{W118}. The source reports lower immediate quiz scores with AI assistance; its percentage normalization is unresolved (Appendix~\ref{app:methodology}, \S\ref{app:commentary-ch10}). Usage-pattern comparisons are exploratory, and delayed retention was not measured.}
\label{fig:ch10-research-2}
\end{figure}

The queue identifies pressure, not which work may safely disappear. Nicole Forsgren and Abi Noda's guidance, excerpted alongside Orosz's interview in \emph{Frictionless}, motivates making workflow friction visible \oroszcite{P078}. For this service, classify the purpose of a delay before optimizing it:
\begin{center}
\footnotesize
\begin{tabularx}{\linewidth}{@{}>{\RaggedRight\arraybackslash}X>{\RaggedRight\arraybackslash}X>{\RaggedRight\arraybackslash}X@{}}
\toprule
\textbf{Delay and purpose} & \textbf{Owner / proposed change} & \textbf{Check} \\
\midrule
Repeated environment setup; avoidable preparation & Platform owner versions the setup procedure. & Setup effort and reproducibility; unchanged permission envelope. \\
Reviewer searches for missing provenance; assurance preparation & Tech lead prepares a versioned evidence packet. & Search time and missing evidence; independent checks retained. \\
Waiting for an INT-002 decision; unresolved authority & Policy owner resolves the scoped question. & Decision latency and traceable authorization; no inferred approval. \\
\bottomrule
\end{tabularx}
\end{center}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/26_Figure_11_1_Architect.jpg}
\caption{AI policies combine multiple governance obligations. Reported subset + conceptual redraw of W150, original Figure 1; \workref{W150}. Source counts of three common intersections (35, 29, 26). Simplified policy-family labels; do not sum them as a sample total. Only selected frequent intersections are shown, not the complete distribution.}
\label{fig:ch11-research-1}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/27_Figure_11_2_Architect.jpg}
\caption{Policy permission is uneven across contribution channels. Reported figures of W150, original Figure 2; \workref{W150}. Published percentages from the policy corpus; the bars represent different question codings, not a shared outcome scale. The sampled policies do not recommend leaving channels ungoverned.}
\label{fig:ch11-research-2}
\end{figure}

Simon Eskildsen's discussion of rough systems estimates, interviewed by Orosz, provides a complementary habit: challenge assumptions before accepting a benchmark at face value \oroszcite{P111}. Transferred here as an author-proposed analogy, rough arithmetic helps identify what to measure. It does not turn an estimate into pilot data.
\begin{center}
\footnotesize
\begin{tabularx}{\linewidth}{@{}>{\RaggedRight\arraybackslash}X>{\RaggedRight\arraybackslash}X@{}}
\toprule
\textbf{Worksheet field} & \textbf{Question before ranking modes} \\
\midrule
Service obligation and owner & Do build, buy and assisted alternatives cover the same maintenance, policy and replay responsibilities? \\
Observed, assumed or unknown & For each input record its unit, source and window. A scenario coefficient remains assumed; missing follow-up remains unknown. \\
Bound and next measurement & Compare a rough effort/resource bound with the candidate estimate. Investigate the largest decision-sensitive gap rather than choosing the more attractive number. \\
\bottomrule
\end{tabularx}
\end{center}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/28_Figure_12_1_Architect.jpg}
\caption{Coding activity can grow faster than production delivery. Conceptual redraw of W095, original Figure 1; \workref{W095}. Diagram retains the original throughput-paradox mechanism but intentionally excludes superseded numeric claims. The mechanism is logical attenuation, not an updated estimate from the later NBER working-paper revision.}
\label{fig:ch12-research-1}
\end{figure}

\includegraphics[width=\linewidth,height=.62\textheight,keepaspectratio]{figures/jpg/29_Figure_12_2_Architect.jpg}
\caption{Knowledge transfer depends on novice exposure to experts. Conceptual redraw of W120, original Figure 1; \workref{W120}. Didactic sketch of the paper’s theoretical skill-distribution dynamics; not its original numerically specified density. The illustrative curves are not fitted labor data.}
\label{fig:ch12-research-2}
\end{figure}
